// DigRF_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module DigRF_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [3:0] c_cfg_sync,
  input logic [7:0] c_cfg_hold,
  input logic [7:0] c_cfg_timeout,
  input logic [7:0] c_ctl_wdata,
  input logic [7:0] c_ctl_addr,
  input logic  c_ctl_rd,
  input logic [7:0] c_rsp_data,
  input logic [4:0] c_int_vec,
  input logic [4:0] c_int_rx_vec,
  input logic  c_tx_on,
  input logic  c_rx_locked,
  input logic  c_ctl_valid,
  input logic  c_ctl_ready,
  input logic  c_rsp_valid,
  input logic  c_int_valid,
  input logic  c_int_ready,
  input logic  c_int_rx,
  input logic  c_rsp_timeout,
  input logic  c_err_code,
  input logic  c_err_frame,
  input logic  c_tx_underrun
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 11;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:10];          // model of every stored word
  logic [11:0] m_set;                // interrupt bits set this clock
  logic m_state_CTL;          // full / valid pulse / available
  logic m_state_RSP;          // full / valid pulse / available
  logic m_state_INT_TX;          // full / valid pulse / available
  logic m_state_INT_RX;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_rsp_timeout) m_set[0] = 1'b1;
    if (c_err_code) m_set[1] = 1'b1;
    if (c_err_frame) m_set[2] = 1'b1;
    if (c_tx_underrun) m_set[3] = 1'b1;
    if (m_state_CTL && c_ctl_ready) m_set[4] = 1'b1;
    if (m_wr && m_map && (m_idx == 6) && m_state_CTL) m_set[5] = 1'b1;
    if (c_rsp_valid && !m_state_RSP) m_set[6] = 1'b1;
    if (c_rsp_valid && m_state_RSP && (m_rd && m_map && m_idx == 7)) m_set[6] = 1'b1;
    if (c_rsp_valid && m_state_RSP && !(m_rd && m_map && m_idx == 7)) m_set[7] = 1'b1;
    if (m_state_INT_TX && c_int_ready) m_set[8] = 1'b1;
    if (m_wr && m_map && (m_idx == 8) && m_state_INT_TX) m_set[9] = 1'b1;
    if (c_int_rx && !m_state_INT_RX) m_set[10] = 1'b1;
    if (c_int_rx && m_state_INT_RX && (m_rd && m_map && m_idx == 9)) m_set[10] = 1'b1;
    if (c_int_rx && m_state_INT_RX && !(m_rd && m_map && m_idx == 9)) m_set[11] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h40102;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_state_CTL <= 0;
      m_state_RSP <= 0;
      m_state_INT_TX <= 0;
      m_state_INT_RX <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'hFFF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFF;
      if (m_wr && m_map && m_idx == 6 && !m_state_CTL) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFF;
      if (m_wr && m_map && m_idx == 6 && !m_state_CTL) m_state_CTL <= 1;
      if (m_state_CTL && c_ctl_ready) m_state_CTL <= 0;
      if (c_rsp_valid && (!m_state_RSP || (m_rd && m_map && m_idx == 7))) begin
        m_w[7] <= (32'(c_rsp_data[7:0]) << 0);
        m_state_RSP <= 1;
      end else if ((m_rd && m_map && m_idx == 7)) m_state_RSP <= 0;
      if (m_wr && m_map && m_idx == 8 && !m_state_INT_TX) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 8 && !m_state_INT_TX) m_state_INT_TX <= 1;
      if (m_state_INT_TX && c_int_ready) m_state_INT_TX <= 0;
      if (c_int_rx && (!m_state_INT_RX || (m_rd && m_map && m_idx == 9))) begin
        m_w[9] <= (32'(c_int_rx_vec[4:0]) << 0);
        m_state_INT_RX <= 1;
      end else if ((m_rd && m_map && m_idx == 9)) m_state_INT_RX <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h44460200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_INT_RX, m_state_INT_TX, m_state_RSP, m_state_CTL});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return (32'(c_tx_on) << 0) | (32'(c_rx_locked) << 1);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][11:0] & m_w[2][11:0]))
  `SVA_INV(a_core_cfg_sync, c_cfg_sync == m_w[5][3:0])
  `SVA_INV(a_core_cfg_hold, c_cfg_hold == m_w[5][11:4])
  `SVA_INV(a_core_cfg_timeout, c_cfg_timeout == m_w[5][19:12])
  `SVA_INV(a_core_ctl_wdata, c_ctl_wdata == m_w[6][7:0])
  `SVA_INV(a_core_ctl_addr, c_ctl_addr == m_w[6][15:8])
  `SVA_INV(a_core_ctl_rd, c_ctl_rd == m_w[6][16:16])
  `SVA_INV(a_core_int_vec, c_int_vec == m_w[8][4:0])
  `SVA_INV(a_core_ctl_valid, c_ctl_valid == m_state_CTL)
  `SVA_INV(a_core_int_valid, c_int_valid == m_state_INT_TX)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_sync == 4'h2 && c_cfg_hold == 8'h10 && c_cfg_timeout == 8'h40 && c_ctl_wdata == 8'h0 && c_ctl_addr == 8'h0 && c_ctl_rd == 1'h0 && c_int_vec == 5'h0 && !c_ctl_valid && !c_int_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CFG, m_rd && m_map && m_idx == 5)
  `FC(wr_CFG, m_wr && m_map && m_idx == 5)
  `FC(rd_CTL, m_rd && m_map && m_idx == 6)
  `FC(wr_CTL, m_wr && m_map && m_idx == 6)
  `FC(rd_RSP, m_rd && m_map && m_idx == 7)
  `FC(wr_RSP, m_wr && m_map && m_idx == 7)
  `FC(rd_INT_TX, m_rd && m_map && m_idx == 8)
  `FC(wr_INT_TX, m_wr && m_map && m_idx == 8)
  `FC(rd_INT_RX, m_rd && m_map && m_idx == 9)
  `FC(wr_INT_RX, m_wr && m_map && m_idx == 9)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 10)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 10)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_RSP_TIMEOUT_set, m_set[0])
  `FC(irq_RSP_TIMEOUT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_RSP_TIMEOUT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_RSP_TIMEOUT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ERR_CODE_set, m_set[1])
  `FC(irq_ERR_CODE_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ERR_CODE_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ERR_CODE_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_ERR_FRAME_set, m_set[2])
  `FC(irq_ERR_FRAME_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_ERR_FRAME_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_ERR_FRAME_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_UNDERRUN_set, m_set[3])
  `FC(irq_UNDERRUN_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_UNDERRUN_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_UNDERRUN_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_CTL_DONE_set, m_set[4])
  `FC(irq_CTL_DONE_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_CTL_DONE_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_CTL_DONE_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_CTL_OVF_set, m_set[5])
  `FC(irq_CTL_OVF_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_CTL_OVF_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_CTL_OVF_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_RSP_AVAIL_set, m_set[6])
  `FC(irq_RSP_AVAIL_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_RSP_AVAIL_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_RSP_AVAIL_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_RSP_OVF_set, m_set[7])
  `FC(irq_RSP_OVF_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_RSP_OVF_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_RSP_OVF_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(irq_INT_TX_DONE_set, m_set[8])
  `FC(irq_INT_TX_DONE_cleared, m_w[1][8] && m_wr && m_map && m_idx == 1 && PWDATA[8] && PSTRB[1])
  `FC(irq_INT_TX_DONE_masked, m_w[1][8] && !m_w[2][8])
  `FC(irq_INT_TX_DONE_drives_pin, m_w[1][8] && m_w[2][8] && irq)
  `FC(irq_INT_TX_OVF_set, m_set[9])
  `FC(irq_INT_TX_OVF_cleared, m_w[1][9] && m_wr && m_map && m_idx == 1 && PWDATA[9] && PSTRB[1])
  `FC(irq_INT_TX_OVF_masked, m_w[1][9] && !m_w[2][9])
  `FC(irq_INT_TX_OVF_drives_pin, m_w[1][9] && m_w[2][9] && irq)
  `FC(irq_INT_RX_AVAIL_set, m_set[10])
  `FC(irq_INT_RX_AVAIL_cleared, m_w[1][10] && m_wr && m_map && m_idx == 1 && PWDATA[10] && PSTRB[1])
  `FC(irq_INT_RX_AVAIL_masked, m_w[1][10] && !m_w[2][10])
  `FC(irq_INT_RX_AVAIL_drives_pin, m_w[1][10] && m_w[2][10] && irq)
  `FC(irq_INT_RX_OVF_set, m_set[11])
  `FC(irq_INT_RX_OVF_cleared, m_w[1][11] && m_wr && m_map && m_idx == 1 && PWDATA[11] && PSTRB[1])
  `FC(irq_INT_RX_OVF_masked, m_w[1][11] && !m_w[2][11])
  `FC(irq_INT_RX_OVF_drives_pin, m_w[1][11] && m_w[2][11] && irq)
  `FC(CTL_handshake, m_state_CTL && c_ctl_ready)
  `FC(CTL_backpressure, m_state_CTL && !c_ctl_ready)
  `FC(CTL_write_while_full, m_wr && m_map && m_idx == 6 && m_state_CTL)
  `FC(RSP_capture, c_rsp_valid && !m_state_RSP)
  `FC(RSP_overflow, c_rsp_valid && m_state_RSP && !(m_rd && m_map && m_idx == 7))
  `FC(RSP_pop, m_rd && m_map && m_idx == 7 && m_state_RSP)
  `FC(RSP_read_empty, m_rd && m_map && m_idx == 7 && !m_state_RSP)
  `FC(RSP_pop_and_capture, c_rsp_valid && m_state_RSP && m_rd && m_map && m_idx == 7)
  `FC(INT_TX_handshake, m_state_INT_TX && c_int_ready)
  `FC(INT_TX_backpressure, m_state_INT_TX && !c_int_ready)
  `FC(INT_TX_write_while_full, m_wr && m_map && m_idx == 8 && m_state_INT_TX)
  `FC(INT_RX_capture, c_int_rx && !m_state_INT_RX)
  `FC(INT_RX_overflow, c_int_rx && m_state_INT_RX && !(m_rd && m_map && m_idx == 9))
  `FC(INT_RX_pop, m_rd && m_map && m_idx == 9 && m_state_INT_RX)
  `FC(INT_RX_read_empty, m_rd && m_map && m_idx == 9 && !m_state_INT_RX)
  `FC(INT_RX_pop_and_capture, c_int_rx && m_state_INT_RX && m_rd && m_map && m_idx == 9)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind DigRF_apb DigRF_apb_sva u_apb_sva (.*);
